  Ad_bridge_partner_ad_message_facebook: "Concentre su gasto en publicidad en Facebook en los clientes potenciales correctos.  Conecte su cuenta de Facebook Ads con Marketo para crear, actualizar o reemplazar la audiencia personalizada de Facebook con leads de una lista inteligente o estática de Marketo con facilidad.<br/><br/><a href='{0}' target='_blank'>Obtenga más información</a>",
  Ad_bridge_partner_ad_message_mediamath: "Mediante la combinación de la potencia de Marketo con TerminalOne Marketing Operating System de MediaMath, los encargados de marketing pueden generar relaciones con sus audiencias a través de distintos canales con un mayor contexto.<br/><br/><a href='http://launchpoint.marketo.com/mediamath/1553-terminalone-marketing-operating-system' target='_blank'>Obtenga más información</a>",
