Mkt3L10n.socialAppDashboard = {
  Social_Dashboard: "Tablero social",
  Date_of_Activity: "Fecha de actividad",
  Last_Updated: "Última actualización",
  Social_Funnel: "Embudo social",
  Audience: "Audiencia<span style='font-weight:normal'>(Cantidad total de perfiles: {0})</span>",
  Share_Metrics: "Compartir métricas",
  Share_Rate_percentage: "<div style=\"font-weight: bold\">Porcentaje de contenido compartido:</div><p>porcentaje de visitas que generan un contenido compartido.</p><br/><div style=\"font-weight: bold\">Porcentaje de personas que hicieron clic en el contenido compartido:</div> <p>cantidad de clics resultantes por contenido compartido.</p><br/><div style=\"font-weight: bold\">Impacto social:</div><p>proporción de visitas sociales (provenientes de una URL compartida) en comparación con la cantidad de visitas no sociales (provenientes de otras fuentes), expresada en porcentaje.</p><br/>",
  Total_Profiles_number_users_who_signed_social_network: "<div style=\"font-weight: bold\">Cantidad total de perfiles:</div><p>cantidad de usuarios que han iniciado sesión en una red social (o interactuado) a través de una aplicación social.</p><br/> <div style=\"font-weight: bold\">Personas con influencia en medios sociales:</div><p>cantidad de usuarios que han generado al menos una visita recomendada de un vínculo compartido.</p><br/><div style=\"font-weight: bold\">Alcance social:</div><p>suma total de todas las conexiones de los usuarios en una campaña. En el caso de usuarios de redes sociales, se cuenta la cantidad de amigos en el momento de compartir contenido; en el caso de usuarios de correo electrónico, se cuenta la cantidad de destinatarios del correo electrónico creado.</p><br/><div style=\"font-weight: bold\">Impresiones sociales:</div><p>cantidad de veces que se podrían haber visto los mensajes compartidos de una campaña. Esto se calcula multiplicando el alcance social de cada usuario que comparte contenido por la cantidad de veces que han compartido contenido, y estos valores se agregan para todos los usuarios que comparten contenido.</p><br/>",
  Visits_number_sessions_Campaign: "<div style=\"font-weight: bold\">Visitas:</div><p>cantidad de veces que los usuarios han visitado su sitio (sesiones únicas iniciadas por sus visitantes) durante un período determinado. Los usuarios que salen del sitio y regresan en 30 minutos se contarán como parte de la sesión original. Las interrupciones de la actividad de más de 30 minutos o el cierre del navegador y los reinicios darán lugar a una nueva sesión o visita.</p><br/><div style=\"font-weight: bold\">Visitas a la campaña:</div><p>cantidad de visitas que se realizan a todas las campañas en su sitio. Las visitas a una página con varias publicaciones de la misma campaña se contarán como una visita a la campaña. Las visitas a varias páginas con publicaciones de la misma campaña también se contarán como una visita a la campaña.</p><br/><div style=\"font-weight: bold\">Interacciones:</div><p>cantidad de veces que los usuarios han completado una acción social, p. ej., votar, calificar, compartir, escribir un comentario, inscribirse en una oferta, compartir un video, etc. </p><br/><div style=\"font-weight: bold\">Contenidos compartidos:</div><p>cantidad de veces que los usuarios han compartido un mensaje en una red social.</p><br/><div style=\"font-weight: bold\">Clics resultantes:</div><p>cantidad de vistas de la página generadas por los vínculos compartidos de una campaña.</p><br/><div style=\"font-weight: bold\">Conversiones:</div><p>cantidad de veces que los usuarios han realizado una acción específica (por ejemplo, comprar un producto), tal como lo define una secuencia de comandos de conversión aplicada en su sitio. \"Registros\" (o usuarios principiantes que interactúan como resultado de seguir un vínculo compartido que los llevó a su sitio) es el evento de conversión predeterminado en caso de que no se implemente una secuencia de comandos de conversión.</p><br/>",
  Data_will_be_updated_within_24_hours: "Los datos se actualizarán dentro de las 24 horas"
};

