  Ad_bridge_partner_ad_message_rocket_fuel: "La integración de la plataforma Origin de Rocket Fuel con Marketo permite que los encargados de marketing impulsen un retorno de la inversión (ROI) de marketing y publicidad digital sin precedentes mediante la provisión de una experiencia de clientes siempre activa en múltiples canales.<br/><br/><a href='http://launchpoint.marketo.com/rocket-fuel/1594-rocket-fuel-origin-platform' target='_blank'>Obtenga más información</a>",
  Ad_bridge_partner_ad_message_turn: "La integración de Digital Hub de Turn con Marketo permite que los encargados de marketing incrementen la conversión y reduzcan los costos de adquisición de clientes debido a que alcanzan audiencias más relevantes a través de avisos de pantalla, dispositivos móviles, video, redes sociales y televisión programática.<br/><br/><a href='http://launchpoint.marketo.com/turn/1288-turn-dmp' target='_blank'>Obtenga más información</a>",
  Ad_bridge_partner_ad_message_linkedin: "Organice la secuencia de mensajes relevantes a través de avisos de pantalla y en redes sociales para acelerar el tránsito de sus leads por el camino del comprador.  Conecte sus audiencias coincidentes de LinkedIn con Marketo para crear, actualizar o reemplazar un segmento de audiencia de LinkedIn por leads de una lista estática o inteligente de Marketo.<br/><br/><a href='{0}' target='_blank'>Obtenga más información</a>",
  Ad_bridge_partner_ad_message_linkedin_reauthorize: "Actualizamos el conector de audiencias coincidentes de LinkedIn en nuestra versión del primer trimestre de 2018. Actualice el servicio de punto de inicio de audiencias coincidentes de LinkedIn para usar el nuevo conector.<br/><br/><a href='{0}' target='_blank'>Obtenga más información</a>",
  Ad_bridge_partner_ad_message_linkedin_expired: "Marketo no puede iniciar sesión en su cuenta de LinkedIn porque la autenticación ya se venció. Actualice sus credenciales en el punto de inicio e inténtelo nuevamente.<br/><br/><a href='{0}' target='_blank'>Obtenga más información</a>",
  Ad_bridge_partner_ad_message_facebook: "Concentre su gasto en publicidad en Facebook en los clientes potenciales correctos.  Conecte su cuenta de Facebook Ads con Marketo para crear, actualizar o reemplazar la audiencia personalizada de Facebook con leads de una lista inteligente o estática de Marketo con facilidad.<br/><br/><a href='{0}' target='_blank'>Obtenga más información</a>",
  Ad_bridge_partner_ad_message_mediamath: "Mediante la combinación de la potencia de Marketo con TerminalOne Marketing Operating System de MediaMath, los encargados de marketing pueden generar relaciones con sus audiencias a través de distintos canales con un mayor contexto.<br/><br/><a href='http://launchpoint.marketo.com/mediamath/1553-terminalone-marketing-operating-system' target='_blank'>Obtenga más información</a>",
  Ad_bridge_partner_ad_message_liveramp: "Combina el poder de Marketo con el servicio IdentityLink de LiveRamp con los datos incorporados para las iniciativas de marketing a través de los canales digitales. Comuníquese con su ejecutivo de cuentas para obtener más información o inicie sesión a continuación.<br/><br/><a href='https://marketo.vertify.com' target='_blank'>Iniciar sesión</a>",
